def format_bytes(n):
    """Format a byte count into a human-readable size."""
    if n < 1024:
        return f"{n} B"
    elif n < 1048576:  # 1024 * 1024
        return f"{n / 1024:.1f} KB"
    elif n < 1073741824:  # 1024 * 1024 * 1024
        return f"{n / 1048576:.1f} MB"
